import math

def solve_for(a, b, c):
	if b == 0:
		assert a == 1
		return (c, 0)
	else:
		(v, u) = solve_for(b, a % b, c)
		v -= a // b * u
		q = u // b
		u -= b * q
		v += a * q
		return (u, v)
for _ in range(int(input())):
	n = int(input())
	cs = [int(x) for x in input().split()]
	assert len(cs) == n and n >= 1
	n_cs = max(cs) + 1
	c_ct = [cs.count(c) for c in range(n_cs)]
	assert n_cs >= 1 and sum(c_ct) == n and all((x > 0 for x in c_ct))
	if n_cs == 1:
		print(0 if n == 1 else -1)
		continue
	if n_cs >= 3:
		print(sum((x * y for (i, x) in enumerate(c_ct) for y in c_ct[:i])))
		for j in range(n):
			for i in range(n):
				if cs[i] < cs[j] and (cs[i] != 0 or cs[j] != n_cs - 1) or (cs[i] == n_cs - 1 and cs[j] == 0):
					print(i + 1, j + 1)
		continue
	a = c_ct[0]
	b = c_ct[1]
	as_ = [i for i in range(n) if cs[i] == 0]
	bs_ = [i for i in range(n) if cs[i] == 1]
	g = math.gcd(a, b)
	if g > 1:
		print(a * b)
		for i in range(0, a, g):
			for j in range(0, b, g):
				for k in range(0, g):
					print(as_[i + k] + 1, bs_[j + k] + 1)
					for l in range(g):
						if k != l:
							print(bs_[j + l] + 1, as_[i + k] + 1)
	elif a <= 2 or b <= 2:
		print(-1)
	else:
		delta = 2 if max(a, b) % min(a, b) == 1 else 1
		m = a * b - delta
		print(m)
		(u, v) = solve_for(a, b, m)
		assert u >= 0 and v >= 0 and (u * a + v * b == m)
		for i in range(u * a):
			print(as_[i % a] + 1, bs_[i % b] + 1)
		for j in range((a - v) * b, a * b):
			print(bs_[j % b] + 1, as_[j % a] + 1)
